# AOT: SettingSourceExtensions.CreateSettingsControls builds controls by reflection.
#  (a) attr.SettingControlType -> Activator.CreateInstance: keep public parameterless ctors + properties of the annotated type.
#  (b) typeof(ModSettingsEnumDropdown<>).MakeGenericType(enum): no native code for enum instantiations under AOT.
#      Replace with an explicit registry (RegisterEnumDropdown<T>), filled at startup by the app (XboxEnumDropdowns.Register, generated by gen_enum_dropdowns.ps1).
param([string]$Root = 'D:\osu-xbox-scratch\osu-aot\osu.Game')
$path = "$Root\Configuration\SettingSourceAttribute.cs"
$t = [IO.File]::ReadAllText($path)
if ($t -match 'enumDropdownFactories') { "already patched"; return }
$nl = if ($t.Contains("`r`n")) { "`r`n" } else { "`n" }
function N($s) { $s.Replace("`r`n", "`n").Replace("`n", $nl) }

# (a)
$old = 'public Type? SettingControlType { get; set; }'
if (-not $t.Contains($old)) { throw 'SettingControlType declaration not found' }
$t = $t.Replace($old, '[DynamicallyAccessedMembers(DynamicallyAccessedMemberTypes.PublicParameterlessConstructor | DynamicallyAccessedMemberTypes.PublicProperties)]' + $nl + '        public Type? SettingControlType { get; set; }')

# (b) use of the registry
$oldCase = N @'
                    case IBindable bindable:
                        var dropdownType =
'@
$newCase = N @'
                    case IBindable bindable:
                        if (enumDropdownFactories.TryGetValue(bindable.GetType().GetGenericArguments()[0], out var enumFactory))
                        {
                            yield return enumFactory(attr.Label, attr.Description, bindable);
                            break;
                        }

                        var dropdownType =
'@
$oldCase = $oldCase.TrimEnd("`r","`n"); $newCase = $newCase.TrimEnd("`r","`n")
if (-not $t.Contains($oldCase)) { throw 'IBindable case not found (formatting differs)' }
$t = $t.Replace($oldCase, $newCase)

# registry members, placed at the start of the extensions class
$oldCls = 'public static partial class SettingSourceExtensions' + $nl + '    {'
if (-not $t.Contains($oldCls)) { throw 'SettingSourceExtensions class header not found' }
$members = N @'
        private static readonly System.Collections.Generic.Dictionary<Type, Func<LocalisableString, LocalisableString, IBindable, Drawable>> enumDropdownFactories = new();

        /// <summary>
        /// Registers an enum type so that settings bound to <c>Bindable&lt;T&gt;</c> get a dropdown without runtime generic instantiation (Native AOT).
        /// </summary>
        public static void RegisterEnumDropdown<T>() where T : struct, Enum
            => enumDropdownFactories[typeof(T)] = (label, description, bindable) => new ModSettingsEnumDropdown<T>
            {
                LabelText = label,
                TooltipText = description,
                Current = (Bindable<T>)bindable,
            };

'@
$t = $t.Replace($oldCls, $oldCls + $nl + $members.TrimEnd("`r","`n") + $nl)

if ($t -notmatch 'using System\.Diagnostics\.CodeAnalysis;') { $t = [regex]::Replace($t, '^(using System;)', "`$1${nl}using System.Diagnostics.CodeAnalysis;", 'Multiline') }
[IO.File]::WriteAllText($path, $t)
"patched $path"
Select-String -Path $path -Pattern 'CodeAnalysis|enumDropdownFactories|RegisterEnumDropdown|DynamicallyAccessedMembers|^using System;' | ForEach-Object { "$($_.LineNumber): " + $_.Line.Trim().Substring(0, [Math]::Min(110, $_.Line.Trim().Length)) }
